import { expect, test } from 'bun:test';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';

type JsonSchema = { [key: string]: unknown };

// What the iPhone app validates every reply and event against, generated by `scripts/generate-swift.ts`.
const SCHEMAS_PATH = join(import.meta.dir, '../../../apps/ios/Packages/RuimtePulsar/Sources/RuimtePulsar/Generated/schemas.json');
// The closed vocabularies as released apps know them, reviewed by hand: a test run never rewrites it.
const BASELINE_PATH = join(import.meta.dir, 'iphone-vocabularies.json');

const RULE =
    'A released iPhone app validates a reply or event whole and refuses one holding a value it does not know, until an App Store update. ' +
    'The wire only gains optional fields, new requests and new events (root CLAUDE.md, Product rules): carry the new value in a new optional field, ' +
    'or open the vocabulary in `openVocabularies` (packages/contracts/scripts/generate-swift.ts) and keep the old values here until no released app closes it.';

/* Every closed `enum` the app reads in a reply or event, by root and JSON pointer; an open vocabulary has `x-open-enum` instead. */
function closedVocabularies(schemas: Record<string, JsonSchema>): Record<string, string[]> {
    const found: Record<string, string[]> = {};

    for (const [name, root] of Object.entries(schemas)) {
        if (!name.startsWith('event.') && !(name.startsWith('request.') && name.endsWith('.result'))) {
            continue;
        }

        const walk = (value: unknown, path: string, ancestors: Set<object>): void => {
            if (!value || typeof value !== 'object' || ancestors.has(value)) {
                return;
            }

            const parents = new Set(ancestors).add(value);
            const json = value as JsonSchema;

            if (typeof json.$ref === 'string') {
                const target =
                    json.$ref === '#'
                        ? root
                        : json.$ref
                              .slice(2)
                              .split('/')
                              .reduce<unknown>((node, key) => (node as JsonSchema)?.[key.replaceAll('~1', '/').replaceAll('~0', '~')], root);
                walk(target, path, parents);
            }

            if (Array.isArray(json.enum)) {
                found[`${name} ${path}`] = json.enum.map(String).sort();
            }

            for (const [key, child] of Object.entries(json)) {
                if (key === '$defs' || key === '$ref' || key.startsWith('x-')) {
                    continue;
                }

                walk(child, `${path}/${key.replaceAll('~', '~0').replaceAll('/', '~1')}`, parents);
            }
        };

        walk(root, '#', new Set());
    }

    return found;
}

/* What makes the current vocabularies differ from the baseline, each with what to do about it. */
function driftFrom(baseline: Record<string, string[]>, current: Record<string, string[]>): string[] {
    const problems: string[] = [];

    for (const [field, values] of Object.entries(current)) {
        const known = baseline[field];

        if (known === undefined) {
            problems.push(`${field} is a new closed vocabulary: add it to iphone-vocabularies.json as ${JSON.stringify(values)}`);
            continue;
        }

        const added = values.filter((value) => !known.includes(value));

        if (added.length > 0) {
            problems.push(`${field} gained ${added.join(', ')}. ${RULE}`);
        }
    }

    for (const [field, known] of Object.entries(baseline)) {
        const values = current[field];

        if (values === undefined || known.some((value) => !values.includes(value))) {
            problems.push(`${field} no longer closes over ${JSON.stringify(known)}: update iphone-vocabularies.json to ${JSON.stringify(values ?? null)}`);
        }
    }

    return problems;
}

test('no closed vocabulary the iPhone app validates in a reply or event gains a value', async () => {
    const schemas = JSON.parse(await readFile(SCHEMAS_PATH, 'utf8')) as Record<string, JsonSchema>;
    const baseline = JSON.parse(await readFile(BASELINE_PATH, 'utf8')) as Record<string, string[]>;

    expect(driftFrom(baseline, closedVocabularies(schemas))).toEqual([]);
});

test('a value added to a closed vocabulary names the rule, and an opened one asks the baseline to follow', () => {
    const reply = (values: string[] | null) => ({
        'request.git.status.result': { type: 'object', properties: { state: values === null ? { type: 'string', 'x-open-enum': ['open'] } : { enum: values } } }
    });
    const baseline = closedVocabularies(reply(['done', 'open']));

    expect(driftFrom(baseline, closedVocabularies(reply(['done', 'failed', 'open'])))).toEqual([
        `request.git.status.result #/properties/state gained failed. ${RULE}`
    ]);
    expect(driftFrom(baseline, closedVocabularies(reply(['done', 'open'])))).toEqual([]);
    expect(driftFrom(baseline, closedVocabularies(reply(null)))).toEqual([expect.stringContaining('no longer closes over')]);
});
